const MH_TOGGLE = ['light', 'switch', 'fan', 'input_boolean', 'humidifier'];
const MH_DORDER = { climate: 0, cover: 1, lock: 2, alarm_control_panel: 3, light: 4, switch: 5, fan: 6, media_player: 7 };
const MH_UNAV = ['unavailable'];
